useAI:
/**
 * React hook for AI operations with property-based access.
 * Mirrors useStripeBilling pattern exactly.
 *
 * @template K - The property key from AIAPI
 * @param key - Property name to access
 * @param authState - Auth state from useAIAuth hook
 * @param config - Optional AI chat configuration
 * @returns The value of the specified property
 *
 * @example
 * ```typescript
 * const authState = useAIAuth();
 * const messages = useAI('messages', authState);
 * const append = useAI('append', authState);
 * const isLoading = useAI('isLoading', authState);
 * const stop = useAI('stop', authState);
 * const cost = useAI('cost', authState);
 * ```
 */
export declare function useAI<K extends keyof AIAPI>(key: K, authState?: AIAuthState, config?: UseAIChatConfig): AIAPI[K];

useAIAuth:
/**
 * Get auth state for AI feature.
 * Safe to call even if @donotdev/auth is not installed.
 */
export declare function useAIAuth(): AIAuthState;

AIAuthState:
/** Auth state for AI feature */
export interface AIAuthState {
    user: AuthUser | null;
    status: FeatureStatus;
}

UseAIChatConfig:
export interface UseAIChatConfig {
    /** API endpoint for chat (default: '/api/ai/chat') */
    api?: string;
    /** System prompt prepended to conversation */
    systemPrompt?: string;
    /** AI provider */
    provider?: string;
    /** Model ID */
    model?: string;
    /** Max output tokens */
    maxTokens?: number;
    /** Temperature */
    temperature?: number;
    /** Cost markup multiplier (default: 4.0) */
    markup?: number;
    /** Callback on each response with usage data */
    onUsage?: (usage: {
        promptTokens: number;
        completionTokens: number;
        totalTokens: number;
    }) => void;
    /** Callback on error */
    onError?: (error: Error) => void;
    /** Tool definitions to send with requests */
    tools?: Record<string, AIToolDefinition>;
}

UseAIChatReturn:
export interface UseAIChatReturn {
    /** Conversation messages (text content) */
    messages: AIMessage[];
    /** Send a message */
    append: (content: string) => void;
    /** Stop current stream */
    stop: () => void;
    /** Whether a response is streaming */
    isLoading: boolean;
    /** Current error */
    error: Error | undefined;
    /** Clear conversation */
    clearMessages: () => void;
    /** Whether AI is available (auth + consent) */
    isAvailable: boolean;
    /** Current input value (controlled) */
    input: string;
    /** Set input value */
    setInput: (value: string) => void;
    /** Submit the current input */
    handleSubmit: (e?: React.FormEvent) => void;
    /** Cost tracking (billed cost only - provider cost is server-side only) */
    cost: {
        lastCost: AICostResult | null;
        sessionCost: AICostResult;
        formattedBilledCost: string;
    };
    /** Tool calls from the latest assistant message */
    toolCalls: AIToolCall[];
}

UseAICostConfig:
export interface UseAICostConfig {
    /** Markup multiplier (default: 4.0) */
    markup?: number;
}

UseAICostReturn:
export interface UseAICostReturn {
    /** Cost of last request */
    lastCost: AICostResult | null;
    /** Cumulative session cost */
    sessionCost: AICostResult;
    /** Formatted provider cost (e.g., "$0.0032") */
    formattedCost: string;
    /** Formatted billed cost (e.g., "$0.013") */
    formattedBilledCost: string;
    /** Record usage from a completed request */
    recordUsage: (usage: AIUsage, model: string) => void;
    /** Reset session cost */
    reset: () => void;
}

AICostBadge:
/**
 * Cost display badge for admin/SaaS-owner views.
 * Shows billed cost only - provider cost is never exposed to client.
 *
 * @example
 * ```tsx
 * <AICostBadge
 *   sessionCost={cost.sessionCost}
 *   formattedBilledCost={cost.formattedBilledCost}
 * />
 * ```
 */
export declare function AICostBadge({ sessionCost, formattedBilledCost, className, }

AIChatProps:
export interface AIChatProps {
    /** System prompt for the AI */
    systemPrompt?: string;
    /** Placeholder text for the input */
    placeholder?: string;
    /** AI configuration */
    config?: UseAIChatConfig;
    /** Show token usage after each response (default: false - admin feature) */
    showUsage?: boolean;
    /** Show model/provider badge (default: false - admin feature) */
    showModel?: boolean;
    /** Show cost badge (default: false - admin/SaaS-owner feature) */
    showCost?: boolean;
    /** Show message timestamps (default: false) */
    showTimestamps?: boolean;
    /** Show tool calls below messages (default: false) */
    showToolCalls?: boolean;
    /** Callback when a message is sent or received */
    onMessage?: (role: 'user' | 'assistant', content: string) => void;
    /** Callback with usage data after each response (for SaaS owner tracking) */
    onUsage?: (usage: AIUsage) => void;
    /** Callback when an error occurs */
    onError?: (error: Error) => void;
    /** Custom className */
    className?: string;
}

AICostBadgeProps:
export interface AICostBadgeProps {
    /** Session cost data */
    sessionCost: AICostResult;
    /** Formatted billed cost string (with markup applied) */
    formattedBilledCost: string;
    /** Custom className */
    className?: string;
}

formatCost:
/**
 * Format a USD cost for display (e.g., "$0.0032").
 */
export declare function formatCost(cost: number): string;

mergeCosts:
/**
 * Merge two cost results (for cumulative tracking).
 */
export declare function mergeCosts(a: AICostResult, b: AICostResult): AICostResult;
